-- v778 · Only audited changes to public catalogue trames. Existing room snapshots and variant manuscripts are untouched.
-- Every replacement is keyed to its verified original text; safe to re-run.
WITH edits (scenario_id,old_title,old_text,new_title,new_text) AS (
 VALUES
  ('001', 'CHRONOLOGIE DU PALIER', 'À 02 h 11, Maël appelle l’ami auquel il réclame sa dette. Une silhouette compatible avec cet ami quitte le palier à 02 h 32 ; un visiteur encapuchonné entre dans l’hôtel à 02 h 48. Aucune caméra ne filme l’intérieur de 222.', 'CHRONOLOGIE DU PALIER', 'À 02 h 11, Maël appelle l’ami à qui il réclame une dette. Cet ami semble quitter l’étage à 02 h 32. À 02 h 48, un autre visiteur entre dans l’hôtel. La chambre 222 n’est pas filmée.'),
  ('001', 'DETTE ET ENREGISTREMENT', 'Des messages prouvent que l’ancien ami doit de l’argent à Maël. Une captation enregistrée après 02 h 55 contient l’ordre d’effacer quelque chose, puis des bruits de lutte. Les voix ne sont pas identifiables avec certitude.', 'DETTE ET ENREGISTREMENT', 'Des messages confirment la dette de l’ancien ami. Après 02 h 55, un enregistrement capte un ordre d’effacement et une lutte. Les voix restent difficiles à identifier.'),
  ('001', 'DEUX ALTERCATIONS, UNE LAME', 'Le désordre correspond à deux séquences distinctes : la première avant 02 h 32, la seconde après 02 h 55. Un Opinel ensanglanté et essuyé est retrouvé dans une benne de service. Ces constatations ne prouvent pas qui le portait au moment du coup.', 'DEUX ALTERCATIONS, UNE LAME', 'Deux altercations ont eu lieu, avant 02 h 32 puis après 02 h 55. Un Opinel ensanglanté et essuyé est retrouvé dans une benne. Son porteur reste inconnu.'),
  ('002', 'APPELS IGNORÉS', 'Plusieurs appels de Léon restent sans réponse le soir de sa mort, dont certains destinés à B.', 'APPELS IGNORÉS', 'Plusieurs appels de Léon sont restés sans réponse le soir de sa mort, notamment ceux adressés au proche avec lequel sa relation était devenue conflictuelle.'),
  ('002', 'DERNIER REFUGE', 'Des messages montrent que Léon considérait encore B comme l''une des seules personnes capables de le comprendre.', 'DERNIER REFUGE', 'Léon cherchait encore du soutien auprès de ce même proche, malgré leur relation devenue difficile.'),
  ('004', 'PASSAGE DEVANT L''IMMEUBLE', 'Une caméra de rue montre un véhicule compatible avec celui de C passant devant l''immeuble.', 'PASSAGE DEVANT L''IMMEUBLE', 'Une caméra montre une voiture ressemblant à celle du proche de Sofia qui habitait le quartier passer devant son immeuble.'),
  ('019', 'LE DOSSIER ATTENDU', 'La victime avait annoncé une remise de pièces financières; les copies disponibles ne coïncident pas toutes.', 'LE DOSSIER ATTENDU', 'La victime devait remettre des documents financiers au gala. Les copies récupérées ne concordent pas toutes sur les opérations concernées.'),
  ('019', 'LE DISPOSITIF MODIFIÉ', 'Des déplacements et accès techniques ont changé pendant la soirée. Leur origine doit être vérifiée.', 'LE DISPOSITIF MODIFIÉ', 'Des trajets et des accès techniques ont été modifiés pendant le gala. Les relevés ne précisent pas encore qui a demandé ces changements.'),
  ('019', 'LES COPIES CONTRADICTOIRES', 'Plusieurs versions des registres et des documents circulent; elles nécessitent des recoupements.', 'LES COPIES CONTRADICTOIRES', 'Plusieurs versions des mêmes registres financiers circulent. Elles ne présentent pas toutes les mêmes informations.'),
  ('020', 'UN BÂTIMENT OCCUPÉ', 'La capacité des passages et les règles de circulation exigent une vérification indépendante.', 'UN BÂTIMENT OCCUPÉ', 'Les plans du Bal des Fondateurs prévoient plusieurs issues secondaires. Les journaux montrent que certaines ont été ouvertes avec retard.'),
  ('020', 'DES RÉSERVES À CONTRÔLER', 'Plusieurs éléments techniques doivent être rapprochés des documents de préparation.', 'DES RÉSERVES À CONTRÔLER', 'Des travaux de maintenance étaient encore en cours dans les locaux techniques avant l’incendie. Leur rôle exact dans sa propagation reste incertain.'),
  ('020', 'UNE CHRONOLOGIE À VÉRIFIER', 'Le traitement des alertes et la diffusion des instructions doivent être confrontés aux journaux.', 'UNE CHRONOLOGIE À VÉRIFIER', 'Les journaux du poste de sécurité montrent un délai entre les premiers signaux et l’alarme générale.'),
  ('023', 'L’APPEL', 'Adriano Verri a été touché. Son état dépendra des décisions et protections prises autour de la Table.', 'L’APPEL', 'Un appel confirme qu’Adriano Verri a été blessé. Il ne permet pas d’établir qui l’a attaqué ni la gravité exacte de ses blessures.'),
  ('024', 'CE QUI EST DÉJÀ CONNU', 'Une partie des informations proposées par le détenu figure déjà dans le dossier. Les répéter réduit peu la peine tout en pouvant augmenter son exposition.', 'CE QUI EST DÉJÀ CONNU', 'Plusieurs faits que le détenu propose de révéler figurent déjà dans les pièces saisies par les enquêteurs.'),
  ('024', 'LA PROTECTION', 'La protection n’est pas automatique. Elle dépend d’un accord réellement accepté et de la valeur des informations fournies.', 'LA PROTECTION', 'Le détenu réclame une protection en échange de ses informations. Sa demande ne prouve pas qu’un accord a été accepté.'),
  ('025', 'LES ORDRES', 'Plusieurs décisions attribuées à Vittorio ne possèdent aucune formulation explicite. Il faut reconstruire ce qu’il a demandé, ce qu’il a seulement accepté et ce que ses hommes ont anticipé.', 'LES ORDRES', 'Certaines décisions de Vittorio portent sa validation. D’autres lui sont attribuées sans qu’un ordre écrit ait été retrouvé.'),
  ('025', 'LES AUDIENCES', 'Le Don peut convoquer un membre, l’écouter puis décider de le protéger, le surveiller, l’écarter ou autoriser une sanction. Il ne reçoit pas pour autant la vérité privée de ce joueur.', 'LES DÉCISIONS DU DON', 'Les décisions de protection et de sanction prises au sommet ne sont pas toutes accompagnées d’une instruction écrite.'),
  ('025', 'LE SOMMET', 'Les dossiers précédents convergent vers le même paradoxe : plus le pouvoir est élevé, moins les ordres doivent être explicites.', 'LE SOMMET', 'Des hommes de Vittorio ont commis des violences sans ordre écrit. D’autres actes sont directement liés à ses validations.'),
  ('027', 'DÉTENTION CLANDESTINE', 'Des témoignages concordants confirment que des prisonniers ont été détenus et maltraités sous l’autorité du deuxième suspect.', 'DÉTENTION CLANDESTINE', 'Des témoins décrivent des mauvais traitements dans l’appareil de détention du FDR où travaillait l’un des suspects.'),
  ('027', 'SOURCE TROP PRÉCISE', 'Le troisième suspect fournit spontanément plusieurs détails exacts sur des cadres rivaux, mais beaucoup moins sur ses propres proches.', 'SOURCE TROP PRÉCISE', 'Le cadre supérieur du FDR donne des détails précis sur les dirigeants rivaux, mais presque rien sur ses propres alliés.'),
  ('027', 'INTÉRÊT PERSONNEL', 'Un échange antérieur prouve que le troisième suspect considérait déjà les cadres de la zone comme ses principaux rivaux.', 'INTÉRÊT PERSONNEL', 'Un échange ancien montre que le cadre supérieur du FDR considérait déjà ces dirigeants comme ses rivaux.'),
  ('027', 'LA VÉRITÉ PEUT ÊTRE UNE ARME', 'La majorité des informations livrées par le troisième suspect sont factuellement exactes. Leur sélection, elle, favorise systématiquement la disparition de ses rivaux.', 'LA VÉRITÉ PEUT ÊTRE UNE ARME', 'Les renseignements du cadre supérieur sont souvent exacts, mais concernent surtout ses rivaux. Ses propres alliés y apparaissent peu.'),
  ('028', 'LE TROISIÈME ATTEND', 'Le troisième suspect ne demande ni protection ni évacuation malgré la dégradation du périmètre. Son calme n’établit rien, mais il contredit son récit de simple exécutant.', 'AUCUNE DEMANDE DE PROTECTION', 'Le cadre resté fidèle au FDR ne demande aucune protection malgré la menace sur le périmètre. Il affirme pourtant n’être qu’un exécutant.'),
  ('029', 'PAIEMENT APRÈS LES FAITS', 'Un transfert financier est effectué après une exécution et relie le premier suspect au réseau.', 'PAIEMENT APRÈS LES FAITS', 'Un transfert financier effectué après l’exécution relie l’intermédiaire financier au réseau.'),
  ('029', 'ORDRE AMBIGU', 'Un message du deuxième suspect demande de faire peur sans préciser la violence attendue.', 'ORDRE AMBIGU', 'Le responsable local a envoyé un message demandant de « faire peur », sans préciser jusqu’où aller.'),
  ('029', 'COOPÉRATION', 'Le troisième suspect livre un lieu vérifiable et gagne en crédibilité.', 'COOPÉRATION', 'L’exécutant devenu coopérant a indiqué un lieu dont l’existence a été vérifiée.'),
  ('031', 'LE DOSSIER', 'Recoupez les déclarations des trois chefs avec les pièces reçues par le bureau.', 'RESPONSABILITÉS À ÉTABLIR', 'Les pièces réunies sur la mort des six agents ne suffisent pas encore à répartir les responsabilités entre les trois chefs arrêtés.'),
  ('032', 'LISTE SIGNÉE', 'Une liste d’arrestations porte la signature du premier suspect.', 'LISTE SIGNÉE', 'Une liste d’arrestations porte la signature du chef administratif.'),
  ('032', 'DÉTENTION PROLONGÉE', 'Des registres montrent des prolongations sans ordre écrit validées par le deuxième suspect.', 'DÉTENTION PROLONGÉE', 'Des registres montrent que le responsable de la sécurité a validé des prolongations de détention sans ordre écrit.'),
  ('032', 'NOTE DU PALAIS', 'Une note du troisième suspect désigne un opposant comme priorité.', 'NOTE DU PALAIS', 'Une note du conseiller du palais désigne un opposant comme cible prioritaire.'),
  ('032', 'CORRECTION MANUSCRITE', 'Le premier suspect modifie une liste après avoir été informé d’une détention abusive.', 'CORRECTION MANUSCRITE', 'Le chef administratif a modifié une liste après avoir été averti d’une détention abusive.'),
  ('032', 'CHAÎNE', 'Les archives permettent de séparer cible politique, ordre administratif et exécution sécuritaire.', 'TROIS ÉTAPES', 'Les documents séparent trois étapes : la désignation d’un opposant, l’ordre administratif et son arrestation.'),
  ('033', 'NOMINATION', 'Une nomination contestée est maintenue par le deuxième suspect.', 'NOMINATION', 'Le membre de la famille occupant le poste ministériel a maintenu une nomination contestée.'),
  ('033', 'AGENDA PRIVÉ', 'Des rendez-vous montrent que le troisième suspect était consulté avant plusieurs décisions.', 'AGENDA PRIVÉ', 'Des rendez-vous montrent que le conseiller familial, sans fonction officielle majeure, était consulté avant plusieurs décisions.'),
  ('033', 'POUVOIR RÉEL', 'Les décisions les plus sensibles convergent vers l’avis du troisième suspect malgré son faible titre officiel.', 'POUVOIR RÉEL', 'Plusieurs décisions sensibles ont suivi des réunions avec le conseiller familial, malgré son titre officiel limité.'),
  ('035', 'DERNIER DÉPLACEMENT', 'Un véhicule lié au troisième suspect transporte M-17 quelques heures avant sa mort.', 'DERNIER DÉPLACEMENT', 'Un véhicule lié au relais logistique de CERBÈRES transporte M-17 quelques heures avant sa mort.'),
  ('036', 'RELAIS CERBÈRES', 'Le troisième suspect est relié à une identité déjà présente dans le dossier M-17.', 'RELAIS CERBÈRES', 'L’intermédiaire CERBÈRES présent sur le site est relié à une identité déjà utilisée dans le dossier M-17.'),
  ('038', 'LISTE DÉTRUITE', 'Le troisième suspect détruit une liste de contacts après la mort de M-17.', 'LISTE DÉTRUITE', 'L’opérateur chargé des liaisons de CERBÈRES détruit une liste de contacts après la mort de M-17.'),
  ('039', 'GARDE DU SITE', 'Aucun élément n’établit que le deuxième suspect connaissait l’ensemble de l’objectif stratégique lorsqu’il a accepté le transfert de contrôle.', 'GARDE DU SITE', 'Aucune pièce ne prouve que le responsable de la sécurité du site connaissait l’objectif complet d’ORPHÉE au moment du transfert.'),
  ('039', 'OPTION DE CRISE', 'Le premier suspect a préparé une option politique de dernier recours sans ordre légal confirmé.', 'OPTION DE CRISE', 'Le coordinateur d’ORPHÉE a préparé une solution politique de dernier recours, sans ordre légal confirmé.'),
  ('039', 'TENTATIVE BLOQUÉE', 'Une demande institutionnelle visant à reprendre le contrôle d’ORPHÉE a été bloquée par le troisième suspect.', 'TENTATIVE BLOQUÉE', 'Une demande officielle de reprise d’ORPHÉE a été bloquée par le relais politique lié à CERBÈRES.'),
  ('039', 'POINT ZÉRO', 'Le dossier final confirme que le danger vient de la continuité humaine et politique autour d’ORPHÉE, pas d’un mécanisme technique isolé.', 'RÉSEAU TOUJOURS ACTIF', 'Les archives montrent que des responsables liés à ORPHÉE continuent de coordonner des actions après sa fermeture officielle.'),
  ('041', 'GIRI', 'La dette ancienne a été rappelée juste avant le meurtre et relie l’exécutant à un relais institutionnel.', 'GIRI', 'Un message rappelant une ancienne faveur a été reçu peu avant le meurtre de l’Oyabun. Un relais institutionnel est associé à cet échange.'),
  ('042', 'MAINS SALES', 'La police a utilisé les clans comme intermédiaires pour obtenir ce qu’elle ne pouvait pas demander officiellement.', 'DEMANDES HORS PROCÉDURE', 'Des demandes adressées aux clans proviennent d’un contact policier, mais aucune procédure officielle ne les autorise.'),
  ('043', 'LA DETTE', 'La chaîne la plus cohérente relie une ancienne faveur policière au meurtre matériel puis à une orientation préparée de l’enquête.', 'UNE CHRONOLOGIE TROUBLANTE', 'Les horaires relient un rappel de faveur, un contact policier et une version préparée de l’enquête. Les rôles exacts restent contestés.'),
  ('044', 'LE CONSEIL', 'Les fragments convergent : l’Oyabun voulait sortir du système, le Kobun l’a tué sous une dette activée et un relais policier avait préparé la couverture et l’orientation de l’enquête.', 'TROIS TRACES À RECOUPER', 'Avant le meurtre, un message rappelle une dette ancienne. Après, une version incriminant Arakida est préparée. Des contacts policiers précèdent l’annonce publique.')
), rebuilt AS (
 SELECT p.scenario_id,
  jsonb_agg(
   CASE WHEN x.old_title IS NOT NULL THEN
    jsonb_set(jsonb_set(t.item,'{text}',to_jsonb(x.new_text),true),'{title}',to_jsonb(x.new_title),true)
   ELSE t.item END
   ORDER BY t.ord) AS new_trames,
  count(x.old_title) AS changed_count
 FROM public.igr_v4_scenario_packs p
 CROSS JOIN LATERAL jsonb_array_elements(p.pack->'trames') WITH ORDINALITY t(item,ord)
 LEFT JOIN edits x
  ON x.scenario_id=p.scenario_id AND x.old_title=t.item->>'title'
  AND x.old_text=t.item->>'text'
 GROUP BY p.scenario_id
)
UPDATE public.igr_v4_scenario_packs p
SET pack=jsonb_set(p.pack,'{trames}',b.new_trames,true), updated_at=now()
FROM rebuilt b
WHERE b.scenario_id=p.scenario_id AND b.changed_count>0
RETURNING p.scenario_id, b.changed_count;
